INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('151d1a2b-05df-4448-b1c8-cec038113406', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h2>Form configurator</h2>', '8b997370-df2f-44bf-84ae-0b7db028bebc');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('517a2957-500f-4d9f-9494-9322c85d4a23', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h2>Dati del/i cliente/i (di seguito il «Cliente»)</h2>', '8705b5f3-dbd8-47f7-95e9-7e8809c5c3f5');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d282ab84-536a-4816-8343-0c8ad0eda3f7', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h3>Legale/i rappresentante/i</h3>', 'fac8805e-ee0d-4ffb-8438-041b0a5f8037');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('791e20ec-bcab-4678-bb58-6e04ae793efd', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h3>Mandato di gestione multilinea</h3>', 'b72f570e-1683-4e6c-8156-59c2a30f7ad3');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('61965019-0490-4182-bd3b-f98feeb187a3', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h2>Dichiarazioni</h2>', '63343cfa-d66d-430f-9ef9-e9bb9a085e4e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('979d3c6e-2c3c-424b-a448-ec42410ef884', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>Con riferimento al suindicato mandato di gestione multilinea, nonché al Contratto Unico per la Prestazione di Servizi di Investimento ed alla Richiesta di Attivazione del Servizio di Gestione, il Cliente dichiara: </p>', 'ee4e2a9e-e6cc-4130-ba26-91e1995fcc99');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('462be3b2-a91f-42db-9077-be11480753e3', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<ul><li>di essere consapevole di tutti i rischi connessi a qualsiasi variazione contrattuale e che intende procedere ai sensi e per gli effetti della presente Richiesta di Variazione Linee; </li><li>di essere consapevole del fatto che la presente Richiesta di Variazione Linee può essere sottoscritta, se tale possibilità è resa disponibile da UBS, mediante il servizio E-Signature e che, in tal caso, la Banca utilizza una apposita sezione del servizio Mailbox per la consegna dei seguenti documenti: <ol><li>documentazione informativa precontrattuale prevista dalla normativa di riferimento; </li><li>la presente Richiesta di Variazione Linee in formato elettronico da sottoscrivere mediante il servizio E-Signature; </li><li>la presente Richiesta di Variazione Linee in formato elettronico sottoscritta mediante il servizio E-Signature; </li><li>eventuale comunicazione con cui la Banca conferma l&#39;attivazione dei servizi in relazione alla presente Richiesta di Variazione Linee;</li></ol></li><li>di essere altresì consapevole del fatto che la presente Richiesta di Variazione Linee può essere sottoscritta, se tale possibilità è resa disponibile da UBS, (i) mediante firma elettronica qualificata (o altra tipologia di firma idonea a integrare il requisito della forma scritta ai sensi della normativa tempo per tempo applicabile) fornita da un provider terzo qualificato ai sensi del Regolamento EIDAS oppure (ii) mediante firma digitale, firma elettronica qualificata, firma elettronica avanzata o altra tipologia di firma idonea a integrare il requisito della forma scritta ai sensi della normativa tempo per tempo applicabile messa a disposizione del Cliente da UBS, anche tramite provider terzi, secondo le modalità e la procedura tempo per tempo comunicate dalla Banca.</li></ul>', '384588de-b37a-46e6-904e-db4ec69d2821');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('ef256d9c-c46d-4a44-a901-f0594a90cdab', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h2>Richiesta di variazione linee di gestione del mandato di gestione multilinea</h2>', '7917fb08-d8dd-48b5-8d43-4942c5034e51');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('d5c031f0-b508-4cd6-8d4a-123c20980b1b', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>Linea di gestione (No. di linea)</p>', '3fca4cdc-80b9-4780-8e64-bb54bffe4521');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('223c8eb2-0afe-4af8-98da-e544172ac4a4', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h3>Attivazione</h3>', 'aeb7fa67-10db-4f67-ba5d-09b6dc95af6e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4b9af6f1-5c92-4528-8b27-9aa424b901a2', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h2>Disattivazione Disinvestimento</h2>', 'dab5af1e-1e60-45bc-92c4-23abd7ddd894');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('098fe780-e909-4810-9739-abaecc3985a4', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>Il Cliente autorizza la Banca, in esecuzione del mandato di gestione, ad aprire o chiudere per conto del Cliente conti correnti e/o conti di custodia ed amministrazione titoli accessori e funzionali a ciascuna Linea di Gestione. Tali conti, che saranno regolati dalle relative Condizioni generali di Contratto contenute nel «Contratto Unico per la Prestazione di Servizi di Investimento», sono da intendersi comunque tutti facenti capo al mandato di gestione multi linea.</p>', 'fa0a760a-5e2e-4f33-94b0-4096a6568806');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('4a630429-fe98-4576-a273-40785c400dec', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>Le condizioni economiche relative alla/ nuova/e Linea/e di Gestione, nonché ai conti ad essa/e accessori sono contenute nel documento «Commissioni e Spese» allegato alla presente Richiesta di Variazione Linee (sub Allegato 2).</p>', 'f44808cd-c446-4411-8442-c4885b26d67f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('964f1e05-3dcb-427d-ba31-f214e11ae7ad', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h2>Conferimenti e/o disinvestimenti parziali</h2>', '67060197-f8ae-4388-8230-befacb88be88');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('56abfb9e-490e-4fe9-8c9e-b44669a2951b', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h2>Data di efficacia della richiesta di variazione linee</h2>', '92676b2e-7672-48cf-aaed-d7e38a06e7d0');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('90ec32ca-e98d-4168-986a-c95b674cec7f', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>La presente Richiesta di Variazione Linee del Cliente avrà effetto dal giorno della sottoscrizione.</p>', 'c9086864-8192-43e7-aa72-760fad8730af');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('011d8249-31af-4bf2-b711-4a2d52a9331b', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>In ogni caso, si avverte il Cliente che in considerazione dei tempi tecnici necessari le operazioni di investimento e disinvestimento potrebbero richiedere per l&#39;attuazione un termine massimo di 30 giorni solari dal giorno della disponibilità effettiva della liquidità da parte della Banca (fermo, comunque, restando il rispetto di eventuali soglie minime di conferimento).</p>', 'f082921a-7cac-4c9a-bd51-52ea2bdebbd2');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('8a447ace-a239-4ded-9b2b-ceadc3c456bb', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h2>Firma/e</h2>', 'f81a9166-ef2f-43f7-b95a-7450595f79b8');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('dd1e9868-c600-4a93-84aa-91e64728b18a', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h3>Cliente</h3>', 'd49502b1-78b6-419c-8ca5-61a78e5f45e1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9cd3493e-8456-4d08-bb6a-3e771e25c572', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>Letto, confermato e sottoscritto.</p>', 'd16ce7b2-dec0-4814-ba21-94ffa4b10d47');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('cff2b120-925d-40f6-a261-9b81b2af3bbd', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>Firma del cliente </p>', '5e4f005f-5491-4db1-ade6-f68caf77604f');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('a9a57ac7-aa6f-4135-b571-3a5575ed2cca', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>Firma del legale rappresentante </p>', '86d49b07-5557-475b-9426-9abc2f8298e1');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('773017b2-5053-4f01-a956-ae8f34e8a55c', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<h3>Elenco documenti allegati</h3>', '4d2f8e75-2080-4a7e-91c9-03f9abbc7e1e');
INSERT INTO app_redacto.asset_version (id, created, language, version, status, content, asset_fk_id) VALUES ('9eaf03b4-6f36-4d72-971f-4a7f76405b7b', '2026-09-28 12:01:58.977', 'it', 1, 'DRAFT', '<p>Allegato 1: Caratteristiche della/e Linea/e di Gestione; Allegato 2: Commissioni e Spese (solo in caso di scelta da parte del Cliente di nuova/e Linea/e di Gestione); Allegato 3: Breve descrizione delle principali classi di attivi Allegato 4: Informazioni SFDR (solo per UBS Manage Advanced [Sustainable Investing])</p>', '8de69e3b-5d6a-4709-b958-c726a1552890');
